"""Q&A data part 2: segmentation, activation, governance, query/monitoring, data collection, AJO, CJA, AI, careers."""
TOPICS2 = []
def T(slug, title, desc, intro, items):
    TOPICS2.append(dict(slug=slug, title=title, desc=desc, intro=intro, items=items))

T("segmentation-audiences", "AEP Segmentation & Audiences: Answers",
  "Answers on AEP audiences: streaming, batch and edge segmentation, Segment Builder, PQL, composition, federated audiences and lookalikes.",
  "How audiences are built and evaluated in Adobe Experience Platform and Real-Time CDP.",
  [("What is segmentation in AEP?", "Segmentation defines rules over profile attributes and events to create audiences. The Segmentation Service evaluates them and makes the resulting audiences available for activation and for Adobe applications.", ["seg-types", "pql"]),
   ("What are the segmentation types in AEP?", "Batch evaluates all profiles on a schedule, streaming evaluates qualifying rules continuously as data arrives, and edge evaluates rules at the Edge for same-page personalisation. Each has its own eligibility rules and latency.", ["seg-types", "seg-stream", "seg-edge"]),
   ("Which segmentation type applies to a customer whose balance rises above 10,000 in real time?", "Streaming segmentation, provided the rule is streaming-eligible and the balance attribute arrives through a streaming path. Batch would only qualify after the next scheduled run.", ["seg-stream"]),
   ("How do I segment customers with more than three purchases in seven days?", "Build an audience in Segment Builder using a purchase event count with a rolling seven-day time constraint. Check whether the rule is streaming-eligible or will run in batch.", ["seg-stream", "pql"]),
   ("What is PQL?", "Profile Query Language (PQL) is the language behind audience rules. Segment Builder generates it, and the Segmentation API accepts it for programmatic audience creation.", ["pql"]),
   ("What is edge segmentation?", "Edge segmentation evaluates simple audience rules on the Edge Network so a visitor can be qualified and personalised within the same interaction, using recently collected data.", ["seg-edge"]),
   ("What is audience composition?", "Audience composition lets marketers combine existing audiences with set operations and filters, and optionally bring in data from other sources, in a visual canvas.", ["seg-comp"]),
   ("What is federated audience composition?", "Federated audience composition builds audiences directly on data in your own warehouse and brings the results into Experience Platform without copying the full dataset first. Availability depends on your licence.", ["seg-fed"]),
   ("What is a lookalike audience?", "A lookalike audience finds profiles similar to a seed audience using Adobe's modelling. It is a product capability, so check current availability and licence in the documentation.", ["seg-types"]),
   ("Why does an audience have fewer profiles than expected?", "Common causes: dataset not Profile-enabled, missing identities, the rule uses an attribute that is not populated, a time window that excludes the events, consent or merge policy filtering, or the batch run has not completed.", ["guardrails", "merge", "monitor"]),
   ("Why did batch segmentation finish but streaming did not qualify the profile?", "The rule may not be streaming-eligible, the event may not have been processed yet, or the profile may qualify only under a different merge policy. Check eligibility and processing status.", ["seg-stream", "merge"]),
   ("What is a merge policy's role in segmentation?", "Audiences are evaluated against the profile as merged by a chosen merge policy, so the same rule can return different members under different policies.", ["merge", "seg-types"]),
   ("How do I analyse overlap between audiences?", "Use the audience overlap tools in Segment Builder or audience insights, or query profile exports with Query Service when you need custom analysis.", ["seg-types", "query"]),
   ("How do I group offers or audiences for a festive campaign?", "Audiences are built from rules, so name and tag the campaign audiences consistently. For offers, group them in Offer collections in Journey Optimizer decisioning.", ["seg-types", "ajo"]),
   ("What is the difference between an audience and a segment?", "In current Adobe terminology, audience is the broader term used across products. Segment usually refers to a rule-defined audience built in Segment Builder.", ["seg-types"]),
  ])

T("destinations-activation", "AEP Destinations & Activation: Answers",
  "Answers on AEP destinations: batch, streaming and Edge activation, ad platforms, email tools, mapping, dataset exports and activation governance.",
  "How audiences and data leave Adobe Experience Platform safely.",
  [("What is activation in AEP?", "Activation sends audiences and profile attributes from Experience Platform to destinations such as advertising, email, cloud storage and streaming platforms, after governance checks.", ["dest-types"]),
   ("What types of destinations exist?", "Destination categories include advertising, email marketing, CRM, cloud storage, streaming, social and personalisation destinations. Each has a connector with its own supported identities and export type.", ["dest-types"]),
   ("Which AEP component activates audiences to Facebook or Google Ads?", "Destinations, which are connectors configured in the Destinations catalogue. You select the audience, map identities and attributes, and activate.", ["dest-types"]),
   ("Which feature activates email audiences to Salesforce Marketing Cloud?", "The destination connector for Salesforce Marketing Cloud, configured in the Destinations catalogue, with identity mapping for the email or subscriber key.", ["dest-types"]),
   ("How do batch and streaming activation differ?", "Streaming destinations send updates as audience membership changes. Batch destinations export files on a schedule, for example to cloud storage or email platforms.", ["dest-types", "dest-batch"]),
   ("Why must identities match between AEP and the destination?", "Destinations match on identifiers such as email hash or advertising IDs. Only profiles carrying the supported identity are exported, so missing identifiers reduce the match.", ["dest-types", "xdm-identity"]),
   ("Can I export datasets as well as audiences?", "Yes, dataset export destinations send entire datasets, for example to cloud storage, on a schedule. Check current export options and governance rules.", ["dest-adhoc"]),
   ("What is ad hoc activation?", "Ad hoc activation exports an audience once on demand instead of on the regular schedule, useful for one-off sends.", ["dest-adhoc"]),
   ("How is activation governed?", "Data usage labels on fields, and policies that restrict labelled data for certain marketing actions, are checked when audiences are activated. A violating activation is blocked.", ["labels", "policies"]),
   ("How do I stop sensitive data such as SSN from being activated?", "Apply a sensitive data usage label to the field and a policy that forbids that label for the export marketing action. Also avoid mapping the field in the destination. Do not store government IDs unless required.", ["labels", "policies"]),
   ("Why is my audience not reaching the destination?", "Check the destination flow status, that the audience is mapped and published, identity availability, consent and policy blocks, then dataflow monitoring for errors.", ["monitor", "dest-types"]),
   ("What is the Data Landing Zone used for in activation?", "It can serve as a source of files for ingestion, and some exports can write to cloud storage you manage. Use it when you want a simple file handoff.", ["dlz"]),
  ])

T("governance-privacy-consent", "AEP Governance, Privacy & Consent: Answers",
  "Answers on AEP governance: data usage labels, policies, consent suppression, Privacy Service requests, encryption and GDPR or DPDP handling.",
  "How governance, consent and privacy requests work in Adobe Experience Platform. This is product information, not legal advice.",
  [("What is Data Governance in AEP?", "Data Governance is the set of capabilities for labelling data with usage restrictions, defining policies about allowed marketing actions and enforcing them at activation, plus privacy request handling.", ["labels", "policies"]),
   ("What are data usage labels?", "Labels (called DULE labels) are tags applied to datasets or fields describing how the data may be used, such as contract, sensitive or identifiable data.", ["labels"]),
   ("What are data usage policies?", "Policies connect labels to marketing actions, for example forbidding sensitive-labelled data from being exported to an advertising destination. Enforcement happens when a marketing action is attempted.", ["policies"]),
   ("How do I suppress emails to users who opted out?", "Capture consent and preference data in the profile, for example with the standard consent field group, and exclude opted-out profiles from audiences and journeys. Labels and policies govern data usage; they do not by themselves remove unsubscribed people, so also apply suppression rules.", ["policies", "labels", "ajo"]),
   ("How do I avoid emailing unsubscribed profiles?", "Collect consent and unsubscribe status as profile data, respect them in audience rules, journey conditions and channel-level suppression, and keep your email service provider's suppression list aligned. The Privacy Service handles access and delete requests, not email suppression.", ["privacy", "ajo", "labels"]),
   ("What does the Privacy Service do?", "Privacy Service processes consumer rights requests such as access and delete across Adobe applications. It is available through the UI and the Privacy Service API.", ["privacy"]),
   ("Which API do I use to delete customer data on a GDPR request?", "The Privacy Service API (or the Privacy Service UI) can submit access or delete requests for identities across Adobe applications.", ["privacy"]),
   ("What is the difference between consent and a delete request?", "Consent describes what a person allows. A delete request asks the organisation to remove personal data. They need different handling, and neither replaces the other.", ["privacy", "labels"]),
   ("What is Adobe Experience Platform's role under GDPR or DPDP?", "The platform provides tooling such as labels, policies and Privacy Service requests. The organisation remains responsible for lawful basis, consent, notices and retention. Confirm requirements with your legal team.", ["privacy", "labels"]),
   ("How is data protected in AEP?", "Adobe documents encryption for data in transit and at rest, plus customer-managed key options for some offerings. Check current security documentation for what applies to your licence.", ["encrypt", "protect"]),
   ("How should consent be modelled?", "Use the standard consent and preferences field groups in a profile schema, update them from a consent management source, and make audience and journey rules read them.", ["xdm-profile", "labels"]),
   ("How do I design governance for multiple brands?", "Use sandboxes, role-based access, labels per dataset, brand-specific policies and a consistent consent model, and document who owns which data.", ["labels", "blueprint"]),
  ])

T("query-service-monitoring", "AEP Query Service, Monitoring & Troubleshooting: Answers",
  "Answers on AEP Query Service SQL, derived datasets, data distiller, monitoring dashboards, alerts and debugging failed ingestion.",
  "How to query data and diagnose problems in Adobe Experience Platform.",
  [("What is Query Service?", "Query Service lets you run standard SQL over datasets in the data lake from the UI, a connected client or the API, and write results to derived datasets.", ["query", "query-sql"]),
   ("Which tool lets analysts run SQL on AEP datasets?", "Query Service, available in the UI query editor, through PostgreSQL-compatible clients and through the Query Service API.", ["query"]),
   ("Can Query Service write results back?", "Yes, with CREATE TABLE AS SELECT or INSERT INTO you can produce derived datasets, and they can be Profile-enabled if they use a suitable schema.", ["query-sql", "query-adf"]),
   ("What is Data Distiller?", "Data Distiller is an add-on capability that extends Query Service with advanced SQL functions, scheduling and data preparation. Availability depends on licence.", ["distiller"]),
   ("Are there sample queries?", "Adobe publishes sample queries and templates that you can adapt, for example for identity, event and attribute analysis.", ["query-samples", "query-tpl"]),
   ("Where do I check why ingestion failed?", "Open the Monitoring dashboard, select the dataflow or the batch, and review the error details and failed record reports.", ["monitor"]),
   ("Which dashboard shows ingestion volume trends?", "The Monitoring section shows ingestion and dataflow metrics over time, and you can build reports from observability data.", ["monitor", "observ"]),
   ("What are observability insights?", "Observability insights expose operational metrics about ingestion, Profile and destinations as queryable data so you can build your own dashboards.", ["observ"]),
   ("How do I get alerts on failures?", "Configure alert subscriptions for dataflow, source and destination events in the platform alerts, and route them to email or webhooks.", ["notif"]),
   ("How do I debug missing Web SDK events?", "Use the Adobe Experience Platform Debugger or Assurance to inspect the network call, confirm the datastream and schema, then monitor the dataset for the batch or streaming event.", ["debugger", "assurance", "monitor"]),
   ("How do I check dataset content before using it in CJA?", "Query the dataset in Query Service to confirm that the person ID, timestamp and key fields are populated before creating a connection.", ["query", "cja"]),
   ("How do I troubleshoot a dataset that does not appear in CJA?", "Check that the dataset is in the same sandbox, uses a supported schema class and has a person identifier, and that the connection includes it. Datasets may take time to appear.", ["cja", "cja-faq"]),
  ])

T("web-sdk-data-collection", "Adobe Web SDK & Data Collection: Answers",
  "Answers on Adobe Web SDK: datastreams, XDM events, Tags setup, ECID, data layer, server-side collection and validation.",
  "How to collect clean event data into Adobe Experience Platform.",
  [("What is the Adobe Experience Platform Web SDK?", "The Web SDK (alloy.js) is a single JavaScript library that sends events from web pages to the Edge Network, replacing several older Adobe libraries.", ["websdk", "websdk-install"]),
   ("What is a datastream?", "A datastream is server-side configuration that tells the Edge Network where to send incoming data, such as Experience Platform, Analytics or Target.", ["datastream-prep", "edge-server"]),
   ("How do I install the Web SDK?", "Use the Adobe Tags extension for the Web SDK, create a datastream, configure the extension with its ID, and add rules that send events. You can also install the library directly.", ["websdk-install", "tags-rules"]),
   ("How do I track events with the Web SDK?", "Call sendEvent with an XDM payload, usually through a Tags rule that maps data layer values into XDM fields.", ["websdk-track", "tags-rules"]),
   ("What is the ECID and how is it managed?", "The ECID is the identifier set by the SDK in a first-party cookie. It identifies the device until you link a known identity, such as a login ID, through the identityMap.", ["websdk-ecid"]),
   ("What is the Adobe Client Data Layer?", "A standard JavaScript data layer that publishes page and event data in a predictable structure so tags can map it to XDM.", ["datalayer"]),
   ("How do I validate Web SDK implementation?", "Use the Experience Platform Debugger or Assurance to view requests, XDM payloads and responses, then confirm that events land in the target dataset.", ["debugger", "assurance"]),
   ("How do I map Web SDK data to Adobe Analytics?", "Map XDM fields to Analytics variables through the Analytics settings in the datastream, using the documented mapping of XDM field paths to eVars, props and events.", ["aa-vars", "datastream-prep"]),
   ("What is event forwarding?", "Event forwarding sends collected events from the Edge Network to third-party endpoints server-side, reducing the number of client-side tags.", ["event-fwd"]),
   ("What is the Edge Network server API?", "A server-side API that sends events to the Edge Network with the same data model as the Web SDK, for use outside the browser.", ["edge-server"]),
   ("Why are no events arriving in the dataset?", "Typical causes include the wrong datastream or sandbox, schema validation errors, blocked requests, consent settings, or the dataset not receiving the XDM event class.", ["debugger", "monitor"]),
   ("Which service gives live Edge or Profile Web SDK data in AJO?", "Events from the Web SDK go to the Edge Network, which forwards them to Experience Platform and can trigger journeys that listen to those events.", ["websdk", "ajo"]),
  ])

T("ajo-journeys", "Adobe Journey Optimizer (AJO): Answers",
  "Answers on AJO journeys, events, conditions, frequency capping, re-entry, offer decisioning, testing, reporting and A/B tests.",
  "Questions on designing and operating journeys in Adobe Journey Optimizer.",
  [("What triggers a journey in AJO?", "A journey starts from an event (unitary or business), an audience qualification or an audience read. Events carry the context the journey uses in conditions and messages.", ["ajo"]),
   ("How do I send an SMS when a loan is approved?", "Define an event for loan approval in the schema, build a journey that starts from that event and add an SMS action. Check consent and channel configuration first.", ["ajo"]),
   ("How do I trigger a coupon email shortly after a cart abandonment?", "Collect a cart event through streaming, use it as a journey entry or a timeout condition after the cart, then send the email. Latency depends on the pipeline, so test it end to end.", ["ajo", "stream"]),
   ("How do I stop a journey when an item is out of stock?", "Use a condition on the profile, event or external data in a decision path and route out-of-stock customers to an exit. Ensure the data used is current.", ["ajo"]),
   ("How do I prevent messaging too often?", "Use frequency rules or capping at the channel or journey level in Journey Optimizer, and set re-entry rules so people do not re-trigger the journey too often.", ["ajo"]),
   ("What is re-entry in a journey?", "Re-entry settings decide whether and when a profile can start the same journey again, for example not until the first run has ended or after a wait period.", ["ajo"]),
   ("How do I test a journey before publishing?", "Use test mode with test profiles to simulate events and watch the paths, then review messages with proofs before publishing.", ["ajo-test"]),
   ("What is offer decisioning?", "Offer decisioning picks the best offer for a person using eligibility rules, ranking and constraints, across channels. Offers are grouped in collections and chosen by decisions.", ["ajo"]),
   ("How do I show offers only to gold-tier customers?", "Add an eligibility constraint on the offer, based on a profile attribute or audience such as loyalty tier, so only matching profiles can receive it.", ["ajo"]),
   ("Can I run an A/B test in AJO?", "Yes. Campaigns and journey messages support content experiments, comparing treatments against a goal metric.", ["ajo"]),
   ("Where do I see which journey step has the most drop-off?", "Use the journey reports in AJO for step-level counts, and Customer Journey Analytics when you need deeper cross-channel analysis.", ["ajo", "cja"]),
   ("Which tools combine for push notifications on low data balance?", "AEP supplies profile and event data, and AJO orchestrates the journey and push message, with the Mobile SDK registered for push.", ["ajo", "websdk"]),
   ("How should AJO journeys be designed for resilience?", "Keep journeys small and event-driven, use clear entry and exit conditions, limit external calls, set timeouts, and monitor error paths.", ["ajo"]),
  ])

T("cja-analytics", "Customer Journey Analytics (CJA): Answers",
  "Answers on CJA: connections, data views, stitching, Analysis Workspace, calculated metrics, differences from Adobe Analytics and common issues.",
  "Questions on Customer Journey Analytics and cross-channel reporting.",
  [("When should I use CJA instead of Adobe Analytics?", "Use CJA when you need to analyse several datasets together, such as web, app, call centre and CRM, joined on a person ID, with flexible data views. Adobe Analytics remains suited to web-centric reporting.", ["cja", "cja-faq"]),
   ("How do I combine call-centre and website data into one journey report?", "Bring both datasets into Experience Platform, include a shared person identifier, create a CJA connection to both and build a data view for reporting.", ["cja", "cja-dv"]),
   ("What is a connection in CJA?", "A connection selects the Experience Platform datasets, and the person ID for each, that CJA will use. Data views are then built on top of a connection.", ["cja", "cja-dv"]),
   ("What is a data view?", "A data view defines the dimensions, metrics and settings applied over a connection, such as attribution and session rules, so analysts see consistent reports.", ["cja-dv"]),
   ("What is stitching?", "Stitching links anonymous activity to a known person when a persistent ID appears, so earlier events join the same person for reporting. Review the options in the documentation.", ["cja-stitch"]),
   ("How do I find cross-channel attribution?", "Use CJA data views with attribution models on calculated metrics and Analysis Workspace panels across datasets that share a person ID.", ["cja", "cja-dv"]),
   ("How do I visualise churn or journey paths?", "Use the Flow and Fallout visualisations in Analysis Workspace over the relevant events and segment by cohorts.", ["cja"]),
   ("Does CJA require Real-Time CDP?", "No. CJA works on Experience Platform datasets, and it can use datasets whether or not Profile or Real-Time CDP is licensed. Check your entitlements.", ["cja-faq"]),
   ("How can I analyse call-centre sentiment with purchase history?", "Ingest both sources keyed by customer ID, connect them in CJA and report on sentiment dimensions alongside purchases.", ["cja"]),
   ("How is a person ID chosen for each dataset?", "Pick the field that identifies the person in that dataset, such as a CRM ID or an ECID, in the connection settings. Consistent IDs matter for joining.", ["cja-stitch", "cja"]),
   ("What is a summary dataset in CJA?", "A summary dataset is aggregated data such as campaign cost or targets, brought into CJA for joining with event data in data views.", ["cja-summary"]),
   ("How is CJA different from Query Service?", "Query Service runs SQL for custom analysis and data preparation. CJA provides a reporting interface and managed data views for business users.", ["cja", "query"]),
  ])

T("ai-agentic-mcp", "Agentic AI & MCP for MarTech: Answers",
  "Answers on agentic AI for Adobe MarTech: MCP, agents, safe automation, human-in-the-loop, evaluation, cost and enterprise use cases.",
  "Using AI agents and the Model Context Protocol safely with enterprise MarTech.",
  [("What is MCP?", "The Model Context Protocol (MCP) is an open standard for connecting AI applications to tools and data through servers that expose capabilities in a consistent way.", ["mcp"]),
   ("What is an AI agent?", "An AI agent uses a language model to plan steps and call tools to reach a goal, as opposed to a single prompt and reply. Agents need guardrails, logging and review.", ["mcp"]),
   ("How can agents help with Adobe Experience Platform?", "They can draft schema or query suggestions, summarise monitoring output and prepare documentation by calling approved APIs, with a person reviewing changes before production.", ["apis", "mcp"]),
   ("What are the risks of connecting AI to customer data?", "Risks include leaking personal data, prompt injection from untrusted content, over-broad permissions and unreviewed changes. Apply least privilege, read-only defaults, logging and human approval.", ["labels", "mcp"]),
   ("How do I keep API keys out of the frontend?", "Call models from a server or workflow tool, keep keys in environment variables or a secret manager, and never commit them to Git or ship them to the browser.", ["apis"]),
   ("What is human-in-the-loop?", "A design where an agent proposes and a person approves before an irreversible action, such as publishing, sending or deleting.", ["mcp"]),
   ("How do I evaluate an AI workflow?", "Define success cases and failure cases, test with realistic samples, record outputs, and measure accuracy, cost and latency before expanding scope.", ["mcp"]),
   ("What does the Academy teach about Agentic AI?", "The AI Engineering Bootcamp covers LLM fundamentals, tool use, MCP and workflows with MarTech scenarios. See the programme page for the syllabus and fee on request.", []),
  ])

T("career-training", "Adobe MarTech Careers & Training: Answers",
  "Answers on learning Adobe Experience Platform: roadmap, prerequisites, projects, interview preparation and how the Academy programs are organised.",
  "How to learn Adobe Experience Platform and prepare for MarTech roles. No job, salary or certification outcome is guaranteed.",
  [("What is a good AEP learning roadmap?", "Start with data fundamentals and XDM, then ingestion and Profile, identity and segmentation, destinations, governance, Web SDK collection, AJO and CJA. Practise each stage in a sandbox.", ["learn-arch", "aep"]),
   ("What are the prerequisites for learning AEP?", "Comfort with JSON and basic SQL helps, plus an understanding of web events and marketing channels. No programming background is required for the platform concepts.", ["aep", "learn-arch"]),
   ("How do I get hands-on practice?", "Use a sandbox provided by your employer or training programme. Adobe's tutorials and the Luma demo site give guided exercises.", ["luma", "learn-arch"]),
   ("What topics are covered in AEP interviews?", "Typical areas are XDM modelling, ingestion options, identity and merge policies, segmentation types, governance, Web SDK debugging and journey design. See the interview questions page for practice.", ["xdm-best", "merge", "seg-types"]),
   ("Which Adobe certifications relate to AEP?", "Adobe offers role-based certifications for Experience Platform and related products. Check the current exam guides on Adobe's certification site, as exams change.", ["learn-arch"]),
   ("How does the Academy structure learning?", "Programs combine live sessions, labs and projects. See the AEP Launchpad Bootcamp, the multi-region architecture course and the AI Engineering Bootcamp for syllabus details.", []),
   ("Do you guarantee jobs or certification?", "No. Training improves skills, but no job, salary or certification result is promised.", []),
   ("How do I ask about fees or demo sessions?", "Use the contact form or WhatsApp +91 82968 93895. Demo and webinar details are listed on the Academy pages.", []),
  ])
